const fs=require('fs'),assert=require('assert/strict'),crypto=require('crypto');const {load}=require('./load-ts.cjs');const posts=load('lib/dailyPosts20261103.ts').DAILY_POSTS_20261103;const all=load('lib/blogPosts.ts').BLOG_POSTS;const base='https://www.11plusexampapers.com';
assert.equal(posts.length,5);assert.equal(new Set(all.map(p=>p.slug)).size,all.length);let questions=0;
for(const p of posts){const html=fs.readFileSync('.next/server/app/blog/'+p.slug+'.html','utf8');assert(html.includes('rel="canonical" href="'+base+'/blog/'+p.slug+'"'));assert(!html.includes('content="noindex'));assert(html.includes('property="og:image" content="'+base+p.imageUrl+'"'));assert(html.includes('"image":["'+base+p.imageUrl+'"]'));const hub=fs.readFileSync('.next/server/app/subjects/'+p.subject+'.html','utf8');assert(hub.includes('/blog/'+p.slug));assert(p.content.some(b=>b.text?.includes('/subjects/'+p.subject+')')));for(const b of p.content){for(const target of (b.text||'').matchAll(/\]\((\/[^)]+)\)/g)){const [path,anchor]=target[1].split('#');if(anchor){const targetHtml=fs.readFileSync('.next/server/app'+path+'.html','utf8');assert(targetHtml.includes('id=\"'+anchor+'\"'),'Missing anchor '+target[1])}assert(fs.existsSync('.next/server/app'+path+'.html')||fs.existsSync('.next/server/app'+path+'/index.html')||Object.keys(require('../.next/server/app-paths-manifest.json')).some(k=>k===path+'/page'),'Missing '+path)}}questions+=p.content.filter(b=>b.type==='question').length;assert.equal((html.match(/<details[ >]/g)||[]).length,p.content.filter(b=>b.type==='question').length);assert(!html.includes('<details open'));}
assert.equal(questions,20);
// Independent editorial review of all twenty prompts against the original passages is recorded in the release ledger.
for(const p of posts){const qs=p.content.filter(b=>b.type==='question');assert.equal(qs.length,4);for(const q of qs){assert(q.answer.trim());assert(q.explanation.length>40)}assert(p.content.some(b=>b.text?.includes('exams taken in 2027')));assert(p.content.some(b=>b.text?.includes('possible responses, not official answers')))}
const inv=fs.readFileSync('docs/releases/url-inventory-2026-11-03.txt','utf8').trim().split('\n');const sitemap=fs.readFileSync('.next/server/app/sitemap.xml.body','utf8');for(const u of [...inv,...posts.map(p=>base+'/blog/'+p.slug)])assert(sitemap.includes('<loc>'+u+'</loc>'));assert.equal((sitemap.match(/<loc>/g)||[]).length,256);assert(!/\/(quiz|lesson-preview|test|api)[/<]/.test(sitemap));
for(const x of JSON.parse(fs.readFileSync('docs/artwork/blog-artwork-2026-11-03.json')).items){for(const a of [x.asset,x.thumbnail])assert.equal(crypto.createHash('sha256').update(fs.readFileSync(a.path)).digest('hex'),a.sha256)}console.log('PASS five pages;20 original questions with editorial answer review;canonical/social/schema;reciprocal hub/internal targets;256 sitemap URLs;10 artwork hashes');
